from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.ta_matchers.matchers import Any, Contains, MatchingExpectations
from taf.ul.ettf.msg_capture.expectation_builders.detailed import UniqueMessageDetail
from taf.ul.ettf.msg_capture.expectation_builders import WithStoredArgument
from taf.ul.ettf.msg_capture.storage import AppendToList
from taf.ul.ettf.typed.typed import typed


def s1_type_tgt_to_src_transparent_container(contents):
    return Any({
        'ProtocolIE-Field': Any({
            'value': Any({
                'Target-ToSource-TransparentContainer': contents
            })
        })
    })


def pscell_information_ie(contents=Any()):
    return Any({
        'ProtocolIE-Field': Any({
            'value': Any({
                'PSCellInformation': contents
            })
        })
    })


def user_location_information(element_container, element_aggregator=Contains):
    return Any({
        'ProtocolIE-Field': Any({
            'value': Any({
                'UserLocationInformation': Any({
                    'iE-Extensions': element_aggregator(*element_container)
                })
            })
        })
    })


def full_config(value):
    return MatchingExpectations({'fullConfig-r9': [value]})


def pscell_information_extension():
    return Any({
        'ProtocolExtensionField': Any({
            'extensionValue': Any({
                'PSCellInformation': Any()
            })
        })
    })


class handover(ExpectationsManager):
    @typed(value=str)
    def with_s1_type_full_config(self, value='true'):
        self.append_expectation(UniqueMessageDetail('protocolIEs', s1_type_tgt_to_src_transparent_container(full_config(value)), Contains))

    def with_pscell_information_ie(self):
        self.append_expectation(UniqueMessageDetail('protocolIEs', pscell_information_ie(), Contains))

    def with_pscell_information_inside_user_location_information(self):
        self.store('protocolExtensions', pscell_information_extension(), AppendToList)
        self.append_expectation(UniqueMessageDetail('protocolIEs', WithStoredArgument(user_location_information,
                                                                                      'protocolExtensions'), Contains))
